ALTER TABLE "sales"."returns" DROP CONSTRAINT "ck_sales_returns_rounding_policy";
ALTER TABLE "sales"."returns" ADD CONSTRAINT "ck_sales_returns_rounding_policy" CHECK (rounding_policy IN ('none','nearest_rupee') AND grand_total=net_value_total+(CASE WHEN tax_charge_mechanism='normal' THEN cgst_total+sgst_total+igst_total+cess_total ELSE 0 END)+rounding_adjustment AND ((rounding_policy='none' AND rounding_adjustment=0) OR (rounding_policy='nearest_rupee' AND abs(rounding_adjustment)<=0.50)));
ALTER TABLE "procurement"."purchase_returns" DROP CONSTRAINT "ck_procurement_purchase_returns_rounding_policy";
ALTER TABLE "procurement"."purchase_returns" ADD CONSTRAINT "ck_procurement_purchase_returns_rounding_policy" CHECK (rounding_policy IN ('none','nearest_rupee') AND grand_total=net_value_total+(CASE WHEN tax_charge_mechanism='normal' THEN cgst_total+sgst_total+igst_total+cess_total ELSE 0 END)+rounding_adjustment AND ((rounding_policy='none' AND rounding_adjustment=0) OR (rounding_policy='nearest_rupee' AND abs(rounding_adjustment)<=0.50)));
DROP TRIGGER IF EXISTS tax_portal_documents_immutable_trg ON tax.portal_documents;
RESET ROLE;
